import React from 'react';
import './ProductCard.css';

const ProductCard = ({ product, onQuickShop }) => {
  const whatsappMsg = encodeURIComponent(
    `Hi Ahsan Jewellery, I want to order: ${product.title} (Price: $${product.price})`
  );
  const whatsappUrl = `https://wa.me/923000000000?text=${whatsappMsg}`;

  return (
    <div className="product-card">
      <div className="card-img-box" onClick={() => onQuickShop(product)}>
        <img src={product.image} alt={product.title} />
      </div>

      <div className="card-actions-bar">
        <button 
          className="btn-quickshop" 
          onClick={() => onQuickShop(product)}
        >
          QUICKSHOP
        </button>
        <a 
          href={whatsappUrl} 
          target="_blank" 
          rel="noopener noreferrer" 
          className="btn-add-cart"
        >
          ADD TO CART
        </a>
      </div>

      <div className="card-details">
        <h3 className="card-title" onClick={() => onQuickShop(product)}>
          {product.title}
        </h3>
        <p className="card-price">${product.price.toFixed(2)}</p>
      </div>
    </div>
  );
};

export default ProductCard;
